package com.slotix.reservationcore.policy;
import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="booking_policies") public class BookingPolicy{@Id @GeneratedValue private UUID id;@Column(name="company_id")private UUID companyId;private String name;@Column(name="min_duration_minutes")private int minDurationMinutes;@Column(name="max_duration_minutes")private int maxDurationMinutes;@Column(name="slot_increment_minutes")private int slotIncrementMinutes;@Column(name="min_notice_minutes")private int minNoticeMinutes;@Column(name="max_advance_days")private int maxAdvanceDays;@Column(name="cancellation_notice_minutes")private int cancellationNoticeMinutes;@Column(name="approval_required")private boolean approvalRequired;@Column(name="allow_customer_cancel")private boolean allowCustomerCancel;private String status;@Column(name="created_at")private Instant createdAt;@Column(name="updated_at")private Instant updatedAt;@Column(name="deleted_at")private Instant deletedAt;protected BookingPolicy(){}public static BookingPolicy create(UUID c,String n,int min,int max,int increment,int notice,int advance,int cancellation,boolean approval,boolean cancel){BookingPolicy p=new BookingPolicy();p.companyId=c;p.name=n;p.minDurationMinutes=min;p.maxDurationMinutes=max;p.slotIncrementMinutes=increment;p.minNoticeMinutes=notice;p.maxAdvanceDays=advance;p.cancellationNoticeMinutes=cancellation;p.approvalRequired=approval;p.allowCustomerCancel=cancel;p.status="ACTIVE";p.createdAt=Instant.now();p.updatedAt=p.createdAt;return p;}public UUID getId(){return id;}}
